        //根据option_model_base选项表展示选项
        ;

        BTreeEventFunction.showOption_event = function showOption_event(context, params) {
          BTreeEventFunction.isQuickTag = false;
          if (params.namePathArr == null || params.namePathArr.length == 0) {
            console.error("\u884C\u4E3A\u6811\u4E8B\u4EF6:showOption_event,\u53C2\u6570params.namePathArr\u4E3A\u7A7A");
            return 'running';
          }
          if (params.ids == null || params.ids.length == 0) {
            console.error("\u884C\u4E3A\u6811\u4E8B\u4EF6:showOption_event,\u53C2\u6570params.ids\u4E3A\u7A7A");
            return 'running';
          }
          var allBtn = BTreeEventFunction.btns.get(context.node.uuid);
          if (allBtn != null || allBtn != undefined) {
            allBtn.forEach(function (mbtn) {
              mbtn.node.active = false;
            });
          }
          var nowAllBtns = new Map();
          var _loop = function _loop() {
              var btnCanClick = true;
              var id = params.ids[i];
              var cfg = option_model_base.Inst;
              var tCfg = cfg.Get(id);
              var tObj = context.node.getChildByPath(params.namePathArr[i]);
              if (tObj == null) {
                console.error("\u884C\u4E3A\u6811\u4E8B\u4EF6:showOption_event,params.namePathArr[" + i + "]:" + params.namePathArr[i] + " \u8DEF\u5F84\u4E0D\u5B58\u5728");
                return {
                  v: 'running'
                };
              }
              tObj.active = true;
              var node_on = tObj.getChildByPath("node_on");
              var node_on_lal = tObj.getChildByPath("node_on/lbl_option").getComponent(Label);
              var btn_bg_unlock = tObj.getChildByPath("btn_bg_unlock");
              var btn_bg_unlock_lal = tObj.getChildByPath("btn_bg_unlock/lbl_option").getComponent(Label);
              node_on_lal.string = "";
              btn_bg_unlock_lal.string = "";

              //组合展示的文字
              var str1 = "";
              if (tCfg.tips != 0) str1 = Utils.LAN(tCfg.tips);
              var str2 = "";
              if (tCfg.description != 0) str2 = Utils.LAN(tCfg.description);
              var showStr = i + 1 + "." + (str1 + str2);
              //判断是否能点击和跳转相关
              tCfg.type.forEach(function (typeId) {
                //判断是否可以点击.包括
                if (typeId == 2) {
                  //判断等级是否满足
                  if (BaseDataMgr.playerInfo.playerLevel < tCfg.needlevel) btnCanClick = false;
                } else if (typeId == 3) {
                  //判断资源是否满足
                  tCfg.needresource.forEach(function (item) {
                    var resCount = BaseDataMgr.getResCount(item[0]);
                    if (resCount == null || resCount < item[1]) {
                      btnCanClick = false;
                      return;
                    }
                  });
                } else ;
              });

              //如果不能点击的情况下
              if (!btnCanClick) {
                node_on.active = false;
                btn_bg_unlock.active = true;
                btn_bg_unlock_lal.string = showStr;
              } else {
                node_on.active = true;
                btn_bg_unlock.active = false;
                node_on_lal.string = showStr;
              }

              //判断选项跳转的模块(界面) 当可以点击的时候才注册事件
              if (btnCanClick) {
                var tBtn = tObj.getComponent(Button);
                if (tBtn == null) tBtn = tObj.addComponent(Button);
                nowAllBtns.set(tBtn.node.uuid, tBtn);
                tBtn.node.off(Node.EventType.TOUCH_END);
                tBtn.node.on(Node.EventType.TOUCH_END, function () {
                  PlaySound(2);
                  var allBtn = BTreeEventFunction.btns.get(context.node.uuid);
                  if (allBtn != null || allBtn != undefined) {
                    allBtn.forEach(function (mbtn) {
                      mbtn.node.active = false;
                    });
                  }
                  tObj.parent.parent.parent.parent.active = false;
                  //通过表项的功能枚举打开界面或者跳转界面.没有的话就不打开界面
                  if (tCfg.type.find(function (type) {
                    return type == 1;
                  }) != undefined) {
                    if (tCfg.modulekey == "StaffWorkView") {
                      //打开职位安排界面
                      WindowMgr.open(GameConst.ViewPath.StaffWorkView, {});
                    } else if (tCfg.modulekey == "FoodEquipView") {
                      //打开食物装备界面
                      WindowMgr.open(GameConst.ViewPath.BilllOfFareDetailView, {});
                    } else if (tCfg.modulekey == "BlackValueChange") {
                      EventMgr.emit(ENUM_EVENT_TYPE.EVENT_RESUME_BTREE);
                    }
                  }
                  //判断是否有行为树或者场景配置,有的话就进行相关加载
                  if (tCfg.mapviewbase != "" && tCfg.behaviortree != "") {
                    //有行为树,并且场景也有新的就先加载场景后加载行为树
                    EventMgr.emit(ENUM_EVENT_TYPE.EVENT_CHANGE_ACTION_AND_SCENE, {
                      scenePrefabName: tCfg.mapviewbase,
                      actionName: tCfg.behaviortree
                    });
                  } else if (tCfg.mapviewbase == "" && tCfg.behaviortree != "") {
                    //只有行为树,在当前场景中加载新的行为树
                    EventMgr.emit(ENUM_EVENT_TYPE.EVENT_CHANGE_ACTION, tCfg.behaviortree);
                  }
                });
              }
            },
            _ret;
          for (var i = 0; i < params.ids.length; i++) {
            _ret = _loop();
            if (_ret) return _ret.v;
          }
          BTreeEventFunction.btns.set(context.node.uuid, nowAllBtns);
          EventMgr.emit(ENUM_EVENT_TYPE.EVENT_PAUSE_BTREE);
          return "success";
        }
        //打开界面事件
        ;

        BTreeEventFunction.openView_event = function openView_event(context, params) {
          BTreeEventFunction.isQuickTag = false;
          if (params.viewName == null) {
            console.error("\u884C\u4E3A\u6811\u4E8B\u4EF6:openView_event,\u53C2\u6570params.viewName\u4E3A\u7A7A");
            return 'running';
          }
          if (params.viewName == "StaffWorkView") {
            //打开职位安排界面
            WindowMgr.open(GameConst.ViewPath.StaffWorkView, {});
          } else if (params.viewName == "FoodEquipView") {
            //打开食物装备界面
            WindowMgr.open(GameConst.ViewPath.BilllOfFareDetailView, {});
          }
          return "success";
        }

